function xml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function isoStamp(){return new Date().toISOString().replace(/\D/g,'').slice(0,14)}
function downloadText(name,text,type='text/html'){const u=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)}
function commit(){hist=hist.slice(0,hi+1);hist.push(JSON.stringify(PRJ));if(hist.length>40)hist.shift();hi=hist.length-1}
function undo(n){const next=hi+n;if(next<0||next>=hist.length)return;stopM();hi=next;PRJ=JSON.parse(hist[hi]);genAll();show()}
function validateProject(p){if(!p||p.format!=='slimetribe.foundation'||p.version!==1||!Array.isArray(p.tex)||p.tex.length!==2)throw Error('Neplatný projekt Foundation v1');
 for(const t of p.tex){if(!Number.isInteger(t.seed)||t.seed<0||t.seed>99999||!Number.isInteger(t.scale)||t.scale<2||t.scale>8||!Number.isFinite(t.int)||t.int<0||t.int>100||!Array.isArray(t.c)||t.c.length!==3||!t.c.every(c=>/^#[0-9a-f]{6}$/i.test(c))||!patterns.includes(t.pat))throw Error('Neplatný recept textury')}
 if(!p.songs||!Object.keys(p.songs).length||Object.keys(p.songs).length>100)throw Error('Neplatné skladby');for(const [id,s] of Object.entries(p.songs)){if(!/^[\w-]{1,32}$/.test(id))throw Error('Neplatné ID skladby');p.songs[id]=SND.Song.sanitize(s)}
 p.effects=Object.fromEntries(Object.entries(p.effects||{}).map(([id,e])=>[id,GAME.Sfx.sanitize(e)]));if(!p.synthPatches?.custom1?.osc||!p.synthPatches?.custom1?.aenv||!p.synthPatches?.custom1?.filter)throw Error('Chybí syntetizátor');p.samples||={};return p}
async function loadProject(file){try{if(!file||file.size>12000000)throw Error('Projekt překračuje 12 MB');const next=validateProject(JSON.parse(await file.text()));stopM();PRJ=next;dawSelected=Object.keys(PRJ.songs)[0];for(const [id,item] of Object.entries(PRJ.samples))SND.Library.put('sample',{id,name:item.name||id,data:item.data});genAll();commit();show();$('#notice')&&( $('#notice').textContent='Projekt načten.')}catch(e){alert(e.message)}}
function saveProject(){downloadText('SlimeTribe-project_'+isoStamp()+'.json',JSON.stringify(PRJ,null,2),'application/json')}
function exportHTML(){const d=document.documentElement.cloneNode(true),s=d.querySelector('#foundation-runtime'),code=s.textContent,a=code.indexOf('let PRJ='),b=code.indexOf(';\nlet tab=',a);if(a<0||b<0)throw Error('Export marker missing');s.textContent=code.slice(0,a)+'let PRJ='+JSON.stringify(PRJ).replace(/</g,'\\u003c')+code.slice(b);for(const id of ['#diagnostic-canvas','#cut-fade','#cut-caption'])d.querySelector(id)?.remove();d.querySelector('#cine-timeline-bottom')&&(d.querySelector('#cine-timeline-bottom').innerHTML='');d.querySelector('#pn').innerHTML='';d.querySelector('#nv').innerHTML='';downloadText('SlimeTribe-Phase7_'+isoStamp()+'.html','<!doctype html>\n'+d.outerHTML)}
function texturePNG(){TC[cs].toBlob(b=>{const u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='SlimeTribe-texture-'+cs+'_'+isoStamp()+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(u),3000)},'image/png')}
const patterns=['noise','clouds','stone','brick','wood','metal','sci-fi','organic','ancient','horror','marble','circuit','leather','moss','basalt','runes'];
function show(){const wide=tab==='Hudba'||tab==='Projekt';cw.style.display=wide?'none':'';pn.style.width=wide?'auto':'370px';pn.style.flex=wide?'1':'none';
 $('#nv').innerHTML='<span class="brand">SLIMETRIBE <small>MODELS 0.2</small></span>'+['Základ','Textura','Hudba','Projekt'].map(n=>`<button data-tab="${n}" class="${tab===n?'on':''}">${n}</button>`).join('')+'<button onclick="undo(-1)">↶</button><button onclick="undo(1)">↷</button><button onclick="saveProject()">↓ Projekt</button><button onclick="exportHTML()">↓ HTML</button>';
 if(tab==='Hudba'){dawPanel();return}
 if(tab==='Textura'){cs_=cs;const p=PRJ.tex[cs];pn.innerHTML=`<h2>Procedurální materiály</h2><p>Generátor Eldor · 128 × 128 · opakovatelné seedy</p><select id="slot">${[0,1].map(i=>`<option value="${i}" ${cs===i?'selected':''}>${i===0?'Terén':'Povrch modelů'}</option>`).join('')}</select><select data-tex="pat">${patterns.map(n=>`<option ${p.pat===n?'selected':''}>${n}</option>`).join('')}</select>${['seed','scale','int'].map((k,i)=>`<p>${k} <input data-tex="${k}" type="number" min="${i===1?2:0}" max="${[99999,8,100][i]}" value="${p[k]}"></p>`).join('')}<p>${p.c.map((v,i)=>`<input type="color" data-color="${i}" value="${v}">`).join('')}</p><p>Albedo · normály · výška</p><canvas id="ta" class="th" width="128" height="128"></canvas><canvas id="tn" class="th" width="128" height="128"></canvas><canvas id="th" class="th" width="128" height="128"></canvas><p><button onclick="texturePNG()">↓ PNG</button></p>`;gen(cs);return}
 if(tab==='Projekt'){pn.innerHTML='<h2>Přenosný projekt</h2><p>Všechny recepty textur, skladby, nástroje a efekty jsou součástí JSON a HTML exportu.</p><button onclick="saveProject()">↓ Projekt JSON</button> <button onclick="exportHTML()">↓ Samostatné studio HTML</button><p><label>Načíst projekt <input id="loadProject" type="file" accept=".json,application/json"></label></p><p id="notice">Žádný server, CDN ani síťové načítání. Uložení souborem funguje nezávisle na úložišti prohlížeče.</p>';return}
 pn.innerHTML=`<h2>Nový základ SlimeTribe</h2><p>Vlastní render Eldor a čistě procedurální materiály, hudba a zvuky.</p><div class="studio-card"><b>${xml(window.EldorGLBackend)}</b><p>Lokální režim: ${location.protocol==='file:'?'file:// ✓':xml(location.protocol)}</p><p>Renderovací náhled hladké geometrie. Herní modely a battle/adventure přijdou v dalším kroku.</p></div><p><button onclick="G.paused=!G.paused;pauseSound(G.paused)">Pauza / pokračovat</button> <button onclick="ac();sfx('pick')">Zvuk</button></p><p><button onclick="ac();playM('ambient')">▶ Procedurální hudba</button> <button onclick="stopM()">■ Stop</button></p><p id="notice">Všechny prostředky jsou vložené. Pro zvuk stačí kliknout.</p>`}
$('#nv').addEventListener('click',e=>{if(e.target.dataset.tab){tab=e.target.dataset.tab;show()}});
pn.addEventListener('change',e=>{const el=e.target;if(el.id==='loadProject'){loadProject(el.files[0]);return}if(el.id==='slot'){cs=+el.value;show();return}if(el.dataset.tex){const k=el.dataset.tex;PRJ.tex[cs][k]=k==='pat'?el.value:Math.round(Math.max(+el.min,Math.min(+el.max,+el.value||+el.min)));gen(cs);commit()}if(el.dataset.color!==undefined){PRJ.tex[cs].c[+el.dataset.color]=el.value;gen(cs);commit()}});
function sphereMesh(){const v=[],n=48,m=24;const pt=(a,b)=>{const u=a/n,w=b/m,th=u*Math.PI*2,ph=w*Math.PI,x=Math.sin(ph)*Math.cos(th),y=Math.cos(ph),z=Math.sin(ph)*Math.sin(th);return[x,y,z,x,y,z,1,1,1,u,w]};for(let b=0;b<m;b++)for(let a=0;a<n;a++)v.push(...pt(a,b),...pt(a,b+1),...pt(a+1,b+1),...pt(a,b),...pt(a+1,b+1),...pt(a+1,b));return mk(v)}
const orb=sphereMesh(),floorMesh=mk([[-9,-9,0,0],[9,-9,6,0],[9,9,6,6],[-9,-9,0,0],[9,9,6,6],[-9,9,0,6]].flatMap(([x,z,u,v])=>[x,0,z,0,1,0,1,1,1,u,v]));let time=0,last=0,frames=0;
function frame(ms){requestAnimationFrame(frame);const dt=Math.min(.05,(ms-last)/1000||0);last=ms;if(!G.paused)time+=dt;if(typeof stageUpdate==='function')stageUpdate(dt);if(typeof cutsceneUpdate==='function')cutsceneUpdate(dt);if(typeof gameUpdate==='function')gameUpdate(dt);if(cw.style.display==='none')return;const w=Math.max(1,cv.clientWidth),h=Math.max(1,cv.clientHeight);if(cv.width!==w||cv.height!==h){cv.width=w;cv.height=h}frames++;if(useCanvas2D&&typeof Game!=='undefined'&&Game.Scene.Fallback){if(diagnosticCanvas.width!==w||diagnosticCanvas.height!==h){diagnosticCanvas.width=w;diagnosticCanvas.height=h}Game.Scene.Fallback.draw(w,h);return}if(tab==='Cutscény'&&typeof Game!=='undefined'){Game.Scene.Render.draw(w,h);return}if(tab==='Adventure'&&typeof Game!=='undefined'){Game.Adventure.Editor.draw(w,h);return}if(tab==='Hra'&&typeof Game!=='undefined'){Game.Scene.Render.draw(w,h);return}if(typeof stageDraw==='function'&&['Modely','Mapa','Textura'].includes(tab)){stageDraw(w,h);return}
 if(useCanvas2D){ctx2.fillStyle='#102635';ctx2.fillRect(0,0,w,h);const tex=TC[cs];ctx2.save();ctx2.beginPath();ctx2.arc(w/2,h/2,Math.min(w,h)*.27,0,Math.PI*2);ctx2.clip();ctx2.drawImage(tex,w/2-h*.27,h*.23,h*.54,h*.54);ctx2.restore();$('#status').textContent='Canvas 2D · diagnostický náhled materiálu';return}
 gl.viewport(0,0,w,h);gl.clearColor(.035,.075,.11,1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);gl.useProgram(pg);gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,GT[0]);gl.activeTexture(gl.TEXTURE1);gl.bindTexture(gl.TEXTURE_2D,GT[1]);gl.uniform1i(U.fx,0);gl.uniform1f(U.ft,time);gl.uniform3fv(U.fogc,[.035,.075,.11]);const eye=[Math.sin(time*.12)*7,4.5,Math.cos(time*.12)*7];gl.uniform3fv(U.cam,eye);gl.uniformMatrix4fv(U.vp,false,M.mul(M.persp(.9,w/h,.1,100),M.look(eye,[0,.8,0])));gl.uniform3fv(U.fl,[0,0,0]);gl.uniform1i(U.mode,0);gl.uniformMatrix4fv(U.m,false,M.trs([0,-.25,0],0,1));bindMesh(floorMesh);gl.drawArrays(gl.TRIANGLES,0,floorMesh.n);
 // Eldor shader extension: mode 2 samples original UVs from procedural actor texture.
 gl.uniform1i(U.mode,2);gl.uniformMatrix4fv(U.m,false,M.trs([0,1.2,0],time*.3,1.4));bindMesh(orb);gl.drawArrays(gl.TRIANGLES,0,orb.n);$('#status').textContent=window.EldorGLBackend+' · procedural texture · '+frames+' frames';}
bindDaw();genAll();commit();show();requestAnimationFrame(frame);
window.SlimeTribe={version:'0.2',get project(){return PRJ},get frames(){return frames},get backend(){return window.EldorGLBackend},texturePixels:i=>Array.from(TC[i].getContext('2d').getImageData(0,0,128,128).data),regenerate:genAll,getAudio:()=>({SND,Music:GAME.Music,Sfx:GAME.Sfx}),get transport(){return{running:!!tm,voices:liveNotes.size,state:AC?.state||'locked'}},show:n=>{tab=n;show()},loadProject,exportHTML,saveProject,stop:stopM};
